import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cmath>

// Min-reduction over a single dimension of a contiguous tensor.
// The tensor is viewed as [outer, reduce, inner] and we reduce over the
// middle ("reduce") dimension. For the target workload dim=1 of a
// [128, 4096, 4095] tensor the kernel is purely DRAM-bandwidth bound
// (no data reuse), so the goal is to maximize the number of
// outstanding coalesced loads.
//
// Optimization: split-K with a two-pass combine.
// The previous version assigned each pair of outputs to one thread
// that serially scanned the whole reduce dimension. With only
// outer*inner/2 independent work units and a grid capped at one
// resident wave, each thread owned 1.33 units on average, so the
// threads holding 2 units ran twice as long as the threads holding
// 1, leaving a large imbalance tail (the profiler reports SMs up to
// 21% below average activity and ~90% achieved occupancy).
// Splitting the reduction dimension into `splits` chunks multiplies
// the number of independent work units by `splits`. Choosing
// `splits` so that outer*inner*splits is (nearly) a multiple of the
// resident-thread count makes every thread execute the same number
// of equal-length chunks, removing the imbalance (for the target
// workload splits=3 gives exactly 8 chunks per thread). Partial
// minima land in a small [splits, outer*inner] scratch buffer
// (~6 MB, ~0.1% of the input volume) and a tiny second kernel
// reduces the partials per output. Consecutive threads still own
// consecutive (outer, inner) elements within the same chunk, so
// all global reads stay fully coalesced, and a 4-way unrolled loop
// keeps four independent streaming loads in flight per thread.
__global__ void min_reduce_dim_kernel(const float* __restrict__ x,
                                      float* __restrict__ partials,
                                      long long total,
                                      long long reduce,
                                      long long inner,
                                      long long splits) {
    long long units = total * splits;
    long long stride = (long long)gridDim.x * blockDim.x;
    long long chunk = (reduce + splits - 1) / splits;
    for (long long u = (long long)blockIdx.x * blockDim.x + threadIdx.x;
         u < units; u += stride) {
        long long out_idx = u % total;
        long long s = u / total;
        long long o = out_idx / inner;
        long long j = out_idx - o * inner;
        long long i0 = s * chunk;
        long long i1 = i0 + chunk < reduce ? i0 + chunk : reduce;
        if (i0 >= reduce) {
            // Degenerate chunk (splits > reduce); +inf is the
            // identity element for min.
            partials[s * total + out_idx] = __int_as_float(0x7f800000);
            continue;
        }
        const float* p = x + o * reduce * inner + i0 * inner + j;
        // Eight independent partial minima shorten the loop-carried
        // fminf dependency chain further and keep more independent
        // coalesced streaming loads in flight per thread.
        float a0 = p[0];
        float a1 = a0;
        float a2 = a0;
        float a3 = a0;
        float a4 = a0;
        float a5 = a0;
        float a6 = a0;
        float a7 = a0;
        p += inner;
        long long i = i0 + 1;
        for (; i + 7 < i1; i += 8) {
            float v0 = __ldg(p);
            float v1 = __ldg(p + inner);
            float v2 = __ldg(p + 2 * inner);
            float v3 = __ldg(p + 3 * inner);
            float v4 = __ldg(p + 4 * inner);
            float v5 = __ldg(p + 5 * inner);
            float v6 = __ldg(p + 6 * inner);
            float v7 = __ldg(p + 7 * inner);
            a0 = fminf(a0, v0);
            a1 = fminf(a1, v1);
            a2 = fminf(a2, v2);
            a3 = fminf(a3, v3);
            a4 = fminf(a4, v4);
            a5 = fminf(a5, v5);
            a6 = fminf(a6, v6);
            a7 = fminf(a7, v7);
            p += 8 * inner;
        }
        for (; i < i1; ++i) {
            a0 = fminf(a0, __ldg(p));
            p += inner;
        }
        partials[s * total + out_idx] =
            fminf(fminf(fminf(a0, a1), fminf(a2, a3)),
                  fminf(fminf(a4, a5), fminf(a6, a7)));
    }
}
// Second pass: reduce the `splits` partial minima of each output.
// Reads/writes are fully coalesced and touch only ~0.1% of the
// input volume.
__global__ void min_reduce_combine_kernel(const float* __restrict__ partials,
                                           float* __restrict__ out,
                                           long long total,
                                           long long splits) {
    long long stride = (long long)gridDim.x * blockDim.x;
    if ((total & 3LL) == 0) {
        long long vtotal = total >> 2;
        const float4* __restrict__ p4 = reinterpret_cast<const float4*>(partials);
        float4* __restrict__ o4 = reinterpret_cast<float4*>(out);
        for (long long v = (long long)blockIdx.x * blockDim.x + threadIdx.x;
             v < vtotal; v += stride) {
            float4 m = p4[v];
            for (long long s = 1; s < splits; ++s) {
                float4 t = p4[s * vtotal + v];
                m.x = fminf(m.x, t.x);
                m.y = fminf(m.y, t.y);
                m.z = fminf(m.z, t.z);
                m.w = fminf(m.w, t.w);
            }
            o4[v] = m;
        }
    } else {
        for (long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
             idx < total; idx += stride) {
            float m = partials[idx];
            for (long long s = 1; s < splits; ++s) {
                m = fminf(m, partials[s * total + idx]);
            }
            out[idx] = m;
        }
    }
}

torch::Tensor min_reduce(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto xc = x.contiguous();

    int64_t nd = xc.dim();
    TORCH_CHECK(nd >= 1, "x must have at least one dimension");
    if (dim < 0) dim += nd;
    TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");

    long long outer = 1, inner = 1;
    for (int64_t i = 0; i < dim; ++i) outer *= xc.size(i);
    long long reduce = xc.size(dim);
    for (int64_t i = dim + 1; i < nd; ++i) inner *= xc.size(i);

    std::vector<int64_t> out_shape;
    out_shape.reserve(nd - 1);
    for (int64_t i = 0; i < nd; ++i) {
        if (i != dim) out_shape.push_back(xc.size(i));
    }
    auto out = at::empty(out_shape, xc.options());

    long long total = outer * inner;
    if (total == 0 || reduce == 0) return out;
    const int threads = 256;
    // Cache device/occupancy queries once per process to remove per-call
    // host latency from this DRAM-bound reduction.
    static long long cached_wave = 0;
    static long long cached_waveThreads = 0;
    if (cached_waveThreads == 0) {
        int dev = 0;
        cudaGetDevice(&dev);
        int sms = 0;
        cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
        int blocksPerSm = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(
            &blocksPerSm, min_reduce_dim_kernel, threads, 0);
        if (blocksPerSm < 1) blocksPerSm = 1;
        cached_wave = (long long)sms * blocksPerSm;
        cached_waveThreads = cached_wave * threads;
    }
    long long wave = cached_wave;
    long long waveThreads = cached_waveThreads;
    // Split-K factor: pick the smallest number of reduction chunks whose
    // total unit count gives the block scheduler at least ~8 waves of
    // blocks. The kernel is launched with the full (uncapped) grid so
    // that finished blocks are immediately replaced by the hardware
    // scheduler (work backfill). The previous version capped the grid at
    // one resident wave and statically assigned ~8 chunks per thread;
    // memory-latency variance accumulated over those sequentially
    // executed chunks and showed up as ~60% achieved occupancy (vs 100%
    // theoretical) plus a wide SM-activity imbalance in the profiler.
    // With backfill, faster SMs absorb more blocks and the imbalance
    // tail disappears. Chunks are kept long (>= 256 steps) to preserve
    // streaming efficiency, and consecutive threads still own
    // consecutive (outer, inner) elements so all reads stay coalesced.
    long long splits = 1;
    for (long long s = 1; s <= 16; ++s) {
        if (s > 1 && (reduce + s - 1) / s < 256) break;
        splits = s;
        if (total * s >= 8 * waveThreads) break;
    }
    long long units = total * splits;
    long long blocksNeeded = (units + threads - 1) / threads;
    // Launch the full grid (bounded only by a generous safety cap);
    // the grid-stride loop in the kernel still covers any remainder
    // should the cap ever be reached.
    long long blocksCap = 32 * wave;
    long long blocks = blocksNeeded < blocksCap ? blocksNeeded : blocksCap;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    if (splits == 1) {
        min_reduce_dim_kernel<<<(unsigned int)blocks, threads, 0, stream>>>(
            xc.data_ptr<float>(), out.data_ptr<float>(), total, reduce,
            inner, splits);
    } else {
        auto partials = at::empty({splits, total}, xc.options());
        min_reduce_dim_kernel<<<(unsigned int)blocks, threads, 0, stream>>>(
            xc.data_ptr<float>(), partials.data_ptr<float>(), total,
            reduce, inner, splits);
        long long outBlocksNeeded = (total + threads - 1) / threads;
        long long outBlocks =
            outBlocksNeeded < blocksCap ? outBlocksNeeded : blocksCap;
        min_reduce_combine_kernel<<<(unsigned int)outBlocks, threads, 0,
                                    stream>>>(partials.data_ptr<float>(),
                                              out.data_ptr<float>(), total,
                                              splits);
    }
    return out;
}
"""

